-- TASK-530 — final high-confidence PedMahoratGuli intake batch.
BEGIN; SET LOCAL lock_timeout='8s'; SET LOCAL statement_timeout='120s';
CREATE TEMP TABLE task530_batch12(message_id bigint PRIMARY KEY,construct_code text NOT NULL,lesson_slug text NOT NULL,cognitive public.cognitive_level NOT NULL,difficulty integer NOT NULL,stem_md text NOT NULL,options jsonb NOT NULL CHECK(jsonb_array_length(options)=4),correct_index integer NOT NULL CHECK(correct_index BETWEEN 0 AND 3),explanation_md text NOT NULL,source_reference text GENERATED ALWAYS AS('telegram:@PedMahoratGuli:'||message_id::text||'|task428:expert-rewrite:v1') STORED) ON COMMIT DROP;
INSERT INTO task530_batch12(message_id,construct_code,lesson_slug,cognitive,difficulty,stem_md,options,correct_index,explanation_md)
SELECT (v->>'m')::bigint,v->>'c',v->>'l',(v->>'k')::public.cognitive_level,(v->>'d')::int,v->>'s',v->'o',(v->>'a')::int,v->>'e' FROM jsonb_array_elements($bank$
