{"m":741,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"bilish","d":2,"s":"Pedagogik muloqotning guruh ichidagi asosiy yo‘nalishlarini qaysi javob to‘g‘ri ifodalaydi?","o":["Pedagog–o‘quvchi, pedagog–guruh va guruh–o‘quvchi","Direktor–vazirlik, maktab–tuman va hudud–davlat","Muallif–nashriyot, muharrir–matn va kitob–o‘quvchi","Bino–jihoz, xona–yo‘lak va hovli–maydon"],"a":0,"e":"Pedagogik muloqot bevosita pedagog bilan alohida o‘quvchi, pedagog bilan guruh va guruh orqali alohida o‘quvchi o‘rtasidagi ta’sir yo‘nalishlarida tashkil etilishi mumkin."},
{"m":745,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":2,"s":"O‘qituvchi o‘quvchining qiziqishini tinglamay, uni o‘zi tanlagan fan olimpiadasiga majburladi. Qaysi pedagogik tamoyil buzildi?","o":["Demokratik va shaxsga yo‘naltirilgan yondashuv","Ilmiylik va nazariyaning amaliyot bilan birligi","Ko‘rgazmalilik va tushunarlilik tamoyili","Tizimlilik va izchillik tamoyili"],"a":0,"e":"O‘quvchining qiziqishi, tanlovi va fikrini e’tiborsiz qoldirib qarorni bir tomonlama majburlash demokratik hamda shaxsga yo‘naltirilgan yondashuvga zid."},
{"m":783,"c":"KS.05","l":"xavfsiz-rivojlantiruvchi-talim-muhiti","k":"qollash","d":2,"s":"O‘quvchilar ruhiy va jismoniy toliqib, darsdagi faolligi pasaydi. Pedagog qisqa tinchlanish mashqlari bilan zo‘riqishni kamaytirdi. Qaysi usul qo‘llandi?","o":["Pedagogik relaksatsiya usuli","Yakuniy nazorat usuli","Ma’muriy ogohlantirish usuli","Frontal so‘rov usuli"],"a":0,"e":"Ruhiy va jismoniy zo‘riqishni kamaytirish, diqqatni tiklash va ijobiy hissiy holat yaratishga qaratilgan mashqlar pedagogik relaksatsiya usullaridir."},
{"m":1391,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"qollash","d":2,"s":"Darsda o‘qituvchi tayyor bilimni markazga qo‘ydi, qat’iy intizomni saqladi va o‘quvchilar asosan tingladi. Qaysi paradigma ustuvor?","o":["An’anaviy bilimga yo‘naltirilgan paradigma","Fenomenologik insonparvarlik ta’lim paradigmasi","Tadqiqotga yo‘naltirilgan ta’lim paradigmasi","Hamkorlikka yo‘naltirilgan ta’lim paradigmasi"],"a":0,"e":"Tayyor bilimni o‘qituvchidan o‘quvchiga uzatish, o‘qituvchi markaziy roli va qat’iy intizom an’anaviy bilimga yo‘naltirilgan paradigma belgilaridir."},
{"m":1392,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"qollash","d":2,"s":"Pedagog kerakli xulqni rag‘bat bilan mustahkamlab, nomaqbul xulq oqibatini oldindan belgiladi. Qaysi paradigma yondashuvi namoyon?","o":["Bixevioristik paradigma yondashuvi","Fenomenologik paradigma yondashuvi","Ezoterik paradigma yondashuvi","Konstruktivistik paradigma yondashuvi"],"a":0,"e":"Bixevioristik yondashuv kuzatiladigan xulqni tashqi rag‘bat va oqibatlar orqali shakllantirish hamda mustahkamlashga asoslanadi."},
{"m":1397,"c":"PM.GEN.02","l":"pedagogikaning-asosiy-tamoyillari","k":"bilish","d":2,"s":"Quyidagilardan qaysi biri ta’limning umumiy qonuniyatiga misol bo‘ladi?","o":["Ta’lim sifati maqsad, mazmun va metod uyg‘unligiga bog‘liqligi","Xotira hajmi yoshga qarab bevosita o‘zgarib borishi","Axborot almashinuvi tezligi tanlangan vositaga bog‘liqligi","Guruh tarkibi muloqot shakliga ta’sir qilishi"],"a":0,"e":"Ta’limning umumiy qonuniyatlari butun didaktik jarayonga taalluqli bo‘lib, sifatning maqsad, mazmun, metod, boshqaruv va rag‘batlantirish uyg‘unligiga bog‘liqligini ifodalaydi."},
{"m":1398,"c":"PM.GEN.02","l":"pedagogikaning-asosiy-tamoyillari","k":"bilish","d":2,"s":"Ta’limning ayrim tarkibiy aloqalarini ifodalovchi psixologik, gnoseologik va tashkiliy bog‘lanishlar qaysi guruhga kiradi?","o":["Xususiy ta’lim qonuniyatlariga","Umumiy ta’lim qonuniyatlariga","Huquqiy ta’lim me’yorlariga","Ma’muriy boshqaruv qoidalariga"],"a":0,"e":"Psixologik, gnoseologik, kibernetik, sotsiologik va tashkiliy bog‘lanishlar ta’lim jarayonining muayyan tomonlarini yoritgani uchun xususiy qonuniyatlar sifatida tasniflanadi."},
{"m":1401,"c":"PM.GEN.02","l":"pedagogikaning-asosiy-tamoyillari","k":"bilish","d":2,"s":"Ta’lim mazmunini tanlashga bevosita aloqador tamoyillar qaysi javobda berilgan?","o":["Ilmiylik, insonparvarlik va amaliy yo‘nalganlik","Jazolash, buyruq berish va ma’muriy nazorat","Tezlik, raqobat va tasodifiy tanlash","Hisobot, inventar va moliyaviy rejalashtirish"],"a":0,"e":"Ta’lim mazmuni ilmiy, insonparvar, madaniyat va hayot bilan uyg‘un, fundamental hamda amaliy yo‘nalgan bo‘lishi kerak; bular mazmun tanlash tamoyillaridir."},
{"m":1437,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Kompetensiyaviy yondashuv an’anaviy bilim–ko‘nikma–malaka uchligini qaysi jihat bilan kengaytiradi?","o":["Tajriba va bilimni real faoliyatda qo‘llash qobiliyati bilan","Nazariy ma’lumotlar sonini ko‘paytirish talabi bilan","Dars vaqtini uzaytirish va nazoratni kuchaytirish bilan","Baholarni hisoblashning yangi koeffitsiyenti bilan"],"a":0,"e":"Kompetensiyaviy yondashuv bilim, ko‘nikma va malakani amaliy faoliyat tajribasi hamda ularni real vaziyatlarda mustaqil qo‘llash qobiliyati bilan to‘ldiradi."},
{"m":1487,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"qollash","d":2,"s":"O‘quvchi olimpiadadan keyin boshidan kechirgan voqealar, qarorlar va hislarini guruh bilan tahlil qildi. Qaysi metod qo‘llandi?","o":["Debrifing metodi","Debat metodi","Aqliy hujum metodi","Ma’ruza metodi"],"a":0,"e":"Faoliyat yoki voqeadan keyin ishtirokchilarning tajriba, hissiyot, qaror va xulosalarni tuzilmali muhokama qilishi debrifing metodining mohiyatidir."},
{"m":1560,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Sinf-dars tizimi shakllanishidan oldin o‘quvchilarni birgalikda o‘qitishga asos bo‘lgan ta’lim shakli qaysi?","o":["Guruhli ta’lim shakli","Individual ta’lim shakli","Ma’ruza-seminar shakli","Masofaviy ta’lim shakli"],"a":0,"e":"Tarixiy rivojlanishda guruhli ta’lim o‘quvchilarni yoshi va tayyorgarligiga ko‘ra birgalikda o‘qitishni kuchaytirib, sinf-dars tizimining shakllanishiga zamin yaratgan."},
{"m":1573,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Darsda o‘zlashtirilgan bilim va ko‘nikmalarni kengaytirish, mustahkamlash hamda individual qobiliyatni rivojlantirishga xizmat qiladigan shakl qaysi?","o":["Mustaqil uy ishi","Majburiy yakuniy nazorat","Frontal og‘zaki so‘rov","Ma’muriy yig‘ilish"],"a":0,"e":"Mustaqil uy ishlari darsda o‘rganilganlarni takrorlash, mustahkamlash va chuqurlashtirish, mustaqillik hamda individual layoqatni rivojlantirishga xizmat qiladi."},
{"m":1890,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi ijodkor faoliyatining ahamiyatini aniq mezonlar va dalillar bilan asoslab hukm chiqardi. Bu Bloomning qaysi darajasi?","o":["Baholash darajasi","Yaratish darajasi","Qo‘llash darajasi","Eslab qolish darajasi"],"a":0,"e":"Obyekt yoki g‘oyaning ahamiyati haqida oldindan belgilangan mezon va dalillar asosida hukm chiqarish Bloom taksonomiyasidagi baholash darajasiga kiradi."},
{"m":1891,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi tarixiy g‘oyalarga tayanib, bugungi sharoit uchun yangi islohot loyihasini ishlab chiqdi. Bu Bloomning qaysi darajasi?","o":["Yaratish darajasi","Baholash darajasi","Qo‘llash darajasi","Eslab qolish darajasi"],"a":0,"e":"Oldingi bilim va g‘oyalarni yangi sharoitda birlashtirib, original loyiha yoki reja ishlab chiqish yangilangan Bloom taksonomiyasining yaratish darajasidir."},
{"m":2176,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"qollash","d":2,"s":"Fan o‘qituvchilari umumiy ish jarayonini birgalikda tahlil qilib, vazifalarni muvofiqlashtirdi va jamoaviy qaror chiqardi. Qaysi refleksiya namoyon?","o":["Kooperativ refleksiya","Shaxsiy refleksiya","Intellektual refleksiya","Hissiy refleksiya"],"a":0,"e":"Kooperativ refleksiya jamoaviy faoliyatning rollari, hamkorlik usullari va umumiy natijasini birgalikda anglash hamda keyingi harakatni muvofiqlashtirishga qaratiladi."},
{"m":2177,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"qollash","d":2,"s":"Pedagog nojo‘ya muloqotdan keyin o‘z xatti-harakati, qadriyati va oqibatini tahlil qilib, xulosaga keldi. Qaysi refleksiya ustuvor?","o":["Shaxsiy refleksiya","Kooperativ refleksiya","Intellektual refleksiya","Texnologik refleksiya"],"a":0,"e":"Shaxsiy refleksiya insonning o‘z xatti-harakati, motivi, qadriyati va boshqalarga ta’sirini anglab, o‘zini baholashi va kelgusi xulqini o‘zgartirishiga xizmat qiladi."},
{"m":2181,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":2,"s":"Butun ta’lim tizimi yoki muassasa miqyosida qo‘llanadigan yaxlit pedagogik texnologiya qaysi darajaga kiradi?","o":["Umumpedagogik makro darajaga","Xususiy-metodik mezo darajaga","Lokal mikro darajaga","Individual topshiriq darajasiga"],"a":0,"e":"Umumpedagogik yoki makrotexnologiya muassasa, hudud yoki yaxlit ta’lim jarayoni miqyosidagi maqsad, mazmun va boshqaruv tizimini qamrab oladi."},
{"m":2189,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi matndagi fikrni o‘z so‘zi bilan izohladi va jadval ko‘rinishiga o‘tkazdi. Bu Bloomning qaysi darajasi?","o":["Tushunish darajasi","Eslab qolish darajasi","Qo‘llash darajasi","Tahlil qilish darajasi"],"a":0,"e":"Mazmunni izohlash, misol keltirish, tasniflash yoki bir ifoda shaklidan boshqasiga o‘tkazish Bloom taksonomiyasidagi tushunish darajasiga kiradi."},
{"m":2191,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":1,"s":"O‘quvchi atama, qoida va faktlarni xotiradan aytib berdi. Bu yangilangan Bloom taksonomiyasining qaysi darajasi?","o":["Eslab qolish darajasi","Tushunish darajasi","Qo‘llash darajasi","Tahlil qilish darajasi"],"a":0,"e":"O‘rganilgan atama, fakt, qoida yoki tasnifni tanish va xotiradan qayta aytish yangilangan Bloom taksonomiyasining eslab qolish darajasidir."},
{"m":2192,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":2,"s":"O‘quvchi yaxlit ma’lumotni qismlarga ajratib, ular o‘rtasidagi sababiy bog‘lanishni aniqladi. Bu Bloomning qaysi darajasi?","o":["Tahlil qilish darajasi","Eslab qolish darajasi","Tushunish darajasi","Qo‘llash darajasi"],"a":0,"e":"Yaxlit axborotni qismlarga ajratish, qismlar o‘rtasidagi munosabat va sabab-oqibatni aniqlash Bloom taksonomiyasidagi tahlil qilish darajasiga kiradi."},
{"m":2481,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"qollash","d":1,"s":"O‘quvchi o‘rgangan musbat sonlarga misollarni xotiradan sanab berdi. Bu Bloom taksonomiyasining qaysi darajasi?","o":["Eslab qolish darajasi","Tushunish darajasi","Tahlil qilish darajasi","Yaratish darajasi"],"a":0,"e":"Oldin o‘rganilgan fakt yoki misollarni xotiradan qayta aytish eslab qolish darajasiga kiradi. Manbadagi belgilangan kalit ekspertiza jarayonida tuzatildi."},
{"m":2572,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"qollash","d":2,"s":"Kimyo o‘qituvchisi tajribani o‘zi bajarib, reaksiyadagi rang o‘zgarishini sinfga ko‘rsatdi. Qaysi ta’lim metodi qo‘llandi?","o":["Namoyish metodi","Laboratoriya ishi metodi","Mustaqil mashq metodi","Muammoli bayon metodi"],"a":0,"e":"Tajribani o‘qituvchi bajarib, o‘quvchilar kuzatsa, bu namoyish metodidir. Laboratoriya ishida esa tajribani o‘quvchilar topshiriq va yo‘riqnoma asosida o‘zlari bajaradi."},
{"m":2574,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"qollash","d":2,"s":"O‘qituvchi yurak tuzilishini doskadagi sxema orqali ko‘rsatib, qismlarini nomlashni so‘radi. Qaysi ko‘rgazmali metod ustuvor?","o":["Tasviriy ko‘rsatish metodi","Og‘zaki hikoya metodi","Laboratoriya tajribasi metodi","Mustaqil kitob o‘qish metodi"],"a":0,"e":"Obyektning sxema, rasm yoki chizma ko‘rinishidagi tasviri orqali uning tuzilishini tushuntirish tasviriy ko‘rsatish metodiga kiradi."},
{"m":2716,"c":"KS.05","l":"xavfsiz-rivojlantiruvchi-talim-muhiti","k":"qollash","d":2,"s":"Nizodan so‘ng maktabga kelmay qolgan o‘quvchi bilan pedagog xavfsiz suhbat o‘tkazib, ishonch va yordam taklif qildi. Qaysi harakat bajarildi?","o":["Noqulay vaziyatdagi o‘quvchini qo‘llab-quvvatlash","O‘quvchini omma oldida intizomiy jazolash","Muammoni ota-onaga to‘liq yuklash","Davomat natijasini e’tiborsiz qoldirish"],"a":0,"e":"Ziddiyat yoki noqulay sharoitdagi bolaning qadr-qimmatini himoya qilish, xavfsiz muloqot va amaliy yordam taklif etish rivojlantiruvchi ta’lim muhitining muhim harakatidir."},
{"m":3527,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Bo‘lajak darsni tashkil etish variantlarini mezonlar asosida baholab, eng maqbulini oldindan tanlash qanday jarayon?","o":["Bashoratlash jarayoni","Nazorat qilish jarayoni","Tashxislash jarayoni","Hisobga olish jarayoni"],"a":0,"e":"Bashoratlash rejalashtirilayotgan darsning ehtimoliy variantlari va natijalarini oldindan ko‘rish, ularni mezonlar asosida baholash hamda maqbul yo‘lni tanlashdir."},
{"m":5746,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":2,"s":"O‘qituvchi murakkab mazmunni tushunarli bayon qilib, zamonaviy metodlar yordamida o‘quvchilarning bilim olishini samarali tashkil etdi. Qaysi qobiliyat namoyon?","o":["Didaktik qobiliyat","Akademik qobiliyat","Tashkilotchilik qobiliyati","Perseptiv qobiliyat"],"a":0,"e":"Didaktik qobiliyat o‘quv materialini tushunarli va qiziqarli bayon qilish, mos metodlarni tanlash hamda o‘quvchilarning faol o‘zlashtirishini ta’minlashda namoyon bo‘ladi."},
{"m":9493,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Tashkiliy qism, umumiy takrorlash, nazorat ishini o‘tkazish va uy vazifasini berish qaysi dars turining tuzilishiga xos?","o":["Bilim va ko‘nikmalarni nazorat qilish darsiga","Yangi bilimlarni bayon qilish darsiga","Takrorlash va mustahkamlash darsiga","Laboratoriya amaliy mashg‘uloti darsiga"],"a":0,"e":"Nazorat darsida o‘quvchilar tayyorlanadi, asosiy tushunchalar qisqa yodga olinadi, nazorat topshirig‘i bajariladi va keyingi mustahkamlash uchun vazifa beriladi."},
{"m":9497,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Tashkiliy qism, o‘tilgan mavzu bo‘yicha savol-javob, amaliy topshiriq va baholash qaysi dars turiga xos?","o":["Takrorlash va mustahkamlash darsiga","Yangi bilimlarni bayon qilish darsiga","Bilimlarni yakuniy nazorat qilish darsiga","Laboratoriya mashg‘uloti darsiga"],"a":0,"e":"Oldingi mavzu bo‘yicha savol-javob va amaliy topshiriqlar orqali bilim hamda ko‘nikmalarni qayta ishlash takrorlash va mustahkamlash darsining asosiy tuzilishidir."}
] $bank$::jsonb) source(v);
DO $task530_b12$
DECLARE b task530_batch12%rowtype;actor uuid;subject_id uuid;construct_id uuid;lesson_id uuid;question_id uuid;option_id uuid;option_ids uuid[];i int;n int;bad int;bad_id uuid;bad_code text;bad_source text;
BEGIN
IF (SELECT count(*) FROM task530_batch12)<>28 THEN RAISE EXCEPTION 'TASK530_B12_COUNT';END IF;
IF EXISTS(SELECT 1 FROM task530_batch12 t JOIN public.questions q ON q.source_reference='telegram:@PedMahoratGuli:'||t.message_id OR q.source_reference LIKE 'telegram:@PedMahoratGuli:'||t.message_id||'|%') THEN RAISE EXCEPTION 'TASK530_B12_SOURCE_ALREADY_REPRESENTED';END IF;
SELECT id INTO STRICT actor FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false);IF (SELECT count(*) FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false))<>1 THEN RAISE EXCEPTION 'TASK530_B12_OWNER_NOT_UNIQUE';END IF;SELECT id INTO STRICT subject_id FROM public.subjects WHERE code='informatika';CREATE TEMP TABLE task530_b12_ids(id uuid PRIMARY KEY) ON COMMIT DROP;
FOR b IN SELECT * FROM task530_batch12 ORDER BY message_id LOOP SELECT c.id,l.id INTO STRICT construct_id,lesson_id FROM public.constructs c JOIN public.lesson_constructs lc ON lc.construct_id=c.id JOIN public.lessons l ON l.id=lc.lesson_id WHERE c.code=b.construct_code AND c.is_active AND l.slug=b.lesson_slug AND l.status='published';IF EXISTS(SELECT 1 FROM public.questions q WHERE q.status IN('review','published') AND regexp_replace(lower(btrim(q.stem_md)),'[^[:alnum:]]+','','g')=regexp_replace(lower(btrim(b.stem_md)),'[^[:alnum:]]+','','g')) THEN RAISE EXCEPTION 'TASK530_B12_ACTIVE_EXACT_DUPLICATE_%',b.message_id;END IF;question_id:=gen_random_uuid();INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,author_id,is_generated,source_lesson_id,source_reference) VALUES(question_id,subject_id,construct_id,CASE WHEN b.construct_code LIKE 'KS.%' THEN 'KS' ELSE 'PM.GEN' END,'Y1',b.cognitive,b.difficulty,b.stem_md,'review',NULL,true,lesson_id,b.source_reference);INSERT INTO task530_b12_ids VALUES(question_id);option_ids:=ARRAY[]::uuid[];FOR i IN 0..3 LOOP option_id:=gen_random_uuid();option_ids:=array_append(option_ids,option_id);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(option_id,question_id,'a',i,b.options->>i);END LOOP;INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(question_id,jsonb_build_object('correct_option_id',option_ids[b.correct_index+1]),b.explanation_md);END LOOP;
WITH x AS(SELECT q.id,count(o.id) oc,count(DISTINCT lower(btrim(o.content_md))) dc,count(*)FILTER(WHERE o.id::text=k.payload->>'correct_option_id') kc,min(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) mi,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) ma,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1))FILTER(WHERE o.id::text=k.payload->>'correct_option_id') cw,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1))FILTER(WHERE o.id::text<>k.payload->>'correct_option_id') mw FROM task530_b12_ids r JOIN public.questions q ON q.id=r.id JOIN public.question_options o ON o.question_id=q.id AND btrim(o.side)='a' JOIN public.question_keys k ON k.question_id=q.id GROUP BY q.id)SELECT count(*)FILTER(WHERE oc<>4 OR dc<>4 OR kc<>1 OR mi<1 OR ma>mi*1.8 OR cw>mw*1.25),count(*)INTO bad,n FROM x;IF bad<>0 OR n<>28 THEN RAISE EXCEPTION 'TASK530_B12_BALANCE_%_COUNT_%',bad,n;END IF;
INSERT INTO public.pedagogy_owner_release_waivers(question_id,authorized_by,content_fingerprint,authority,provenance)SELECT q.id,actor,public.professional_question_fingerprint(q.id),'owner_explicit_no_external_expert_20261018','TASK-530 batch 12; owner-delegated AI expert rewrite of PedMahoratGuli items; key independently checked; independent human expert signoff NOT claimed' FROM task530_b12_ids r JOIN public.questions q ON q.id=r.id;GET DIAGNOSTICS n=ROW_COUNT;IF n<>28 THEN RAISE EXCEPTION 'TASK530_B12_WAIVERS_%',n;END IF;
SELECT r.id,q.source_reference,s.finding_code INTO bad_id,bad_source,bad_code FROM task530_b12_ids r JOIN public.questions q ON q.id=r.id CROSS JOIN LATERAL public.pedagogy_semantic_quality_signals(r.id)s WHERE s.severity='high' ORDER BY r.id,s.finding_code LIMIT 1;IF bad_id IS NOT NULL THEN RAISE EXCEPTION 'TASK530_B12_SEMANTIC_%_%',bad_source,bad_code;END IF;
UPDATE public.questions q SET status='published',updated_at=now() FROM task530_b12_ids r WHERE q.id=r.id AND q.status='review';GET DIAGNOSTICS n=ROW_COUNT;IF n<>28 THEN RAISE EXCEPTION 'TASK530_B12_PUBLISHED_%',n;END IF;SELECT count(*) INTO n FROM task530_b12_ids r JOIN public.questions q ON q.id=r.id JOIN public.pedagogy_owner_release_waivers w ON w.question_id=q.id JOIN public.pedagogy_published_revisions p ON p.question_id=q.id WHERE q.status='published' AND w.content_fingerprint=public.professional_question_fingerprint(q.id);IF n<>28 THEN RAISE EXCEPTION 'TASK530_B12_POSTFLIGHT_%_OF_28',n;END IF;
END $task530_b12$;COMMIT;
